/* A08: FDT /chosen linux,initrd-* → phys_initrd_* (setup_machine_fdt skips OF). */
extern unsigned long long phys_initrd_start;
extern unsigned long phys_initrd_size;
extern unsigned long initrd_start, initrd_end;
extern unsigned long long __fdt_pointer;
extern int _printk(const char *fmt, ...);

static unsigned int ggcc_be32(const unsigned char *p)
{
	return ((unsigned int)p[0] << 24) | ((unsigned int)p[1] << 16) |
	       ((unsigned int)p[2] << 8) | (unsigned int)p[3];
}

static int ggcc_str_eq(const char *a, const char *b)
{
	while (*a && *b && *a == *b) {
		a++;
		b++;
	}
	return *a == 0 && *b == 0;
}

/* Returns 1 if initrd found. fdt is a physical/idmap pointer (early boot). */
int ggcc_fdt_scan_initrd(void *fdt)
{
	const unsigned char *base;
	unsigned int totalsize, off_struct, off_strings, struct_size;
	unsigned int p;
	unsigned long long start = 0, end = 0;
	int have_start = 0, have_end = 0;
	int in_chosen = 0;

	if (!fdt)
		return 0;
	base = (const unsigned char *)fdt;
	if (ggcc_be32(base) != 0xd00dfeedu)
		return 0;
	totalsize = ggcc_be32(base + 4);
	off_struct = ggcc_be32(base + 8);
	off_strings = ggcc_be32(base + 12);
	if (off_struct >= totalsize || off_strings >= totalsize)
		return 0;
	struct_size = totalsize - off_struct;
	p = 0;
	while (p + 4 <= struct_size) {
		unsigned int tag = ggcc_be32(base + off_struct + p);
		p += 4;
		if (tag == 9) /* FDT_END */
			break;
		if (tag == 1) { /* BEGIN_NODE */
			const char *name = (const char *)(base + off_struct + p);
			unsigned int nlen = 0;
			while (p + nlen < struct_size && name[nlen])
				nlen++;
			nlen++; /* NUL */
			nlen = (nlen + 3) & ~3u;
			in_chosen = (name[0] == 'c' && ggcc_str_eq(name, "chosen"));
			p += nlen;
			continue;
		}
		if (tag == 2) { /* END_NODE */
			in_chosen = 0;
			continue;
		}
		if (tag == 3) { /* PROP */
			unsigned int len, nameoff;
			const char *pname;
			const unsigned char *val;
			if (p + 8 > struct_size)
				break;
			len = ggcc_be32(base + off_struct + p);
			nameoff = ggcc_be32(base + off_struct + p + 4);
			p += 8;
			if (off_strings + nameoff >= totalsize || p + ((len + 3) & ~3u) > struct_size)
				break;
			pname = (const char *)(base + off_strings + nameoff);
			val = base + off_struct + p;
			if (in_chosen && len >= 8) {
				unsigned long long v = ((unsigned long long)ggcc_be32(val) << 32) |
						       (unsigned long long)ggcc_be32(val + 4);
				if (ggcc_str_eq(pname, "linux,initrd-start")) {
					start = v;
					have_start = 1;
				} else if (ggcc_str_eq(pname, "linux,initrd-end")) {
					end = v;
					have_end = 1;
				}
			}
			p += (len + 3) & ~3u;
			continue;
		}
		/* NOP(4) or unknown: stop to avoid walking off */
		if (tag != 4)
			break;
	}
	if (!have_start || !have_end || end <= start)
		return 0;
	phys_initrd_start = start;
	phys_initrd_size = (unsigned long)(end - start);
	/* Linear map: PAGE_OFFSET(48)=0xffff000000000000, PHYS_OFFSET=0x40000000 */
	initrd_start = (unsigned long)((start - 0x40000000ULL) | 0xffff000000000000ULL);
	initrd_end = initrd_start + phys_initrd_size;
	_printk("ggcc_fdt_scan_initrd: initrd found (phys+linear set)\n");
	return 1;
}

/* A08: walk newc cpio (uncompressed) for /init without VFS. */
unsigned long ggcc_init_blob;
unsigned long ggcc_init_blob_len;
unsigned long ggcc_busybox_blob;
unsigned long ggcc_busybox_blob_len;

static unsigned long ggcc_hex8(const char *s)
{
	unsigned long v = 0;
	int i;
	for (i = 0; i < 8; i++) {
		char c = s[i];
		unsigned long d;
		if (c >= '0' && c <= '9')
			d = (unsigned long)(c - '0');
		else if (c >= 'a' && c <= 'f')
			d = (unsigned long)(c - 'a' + 10);
		else if (c >= 'A' && c <= 'F')
			d = (unsigned long)(c - 'A' + 10);
		else
			return 0;
		v = (v << 4) | d;
	}
	return v;
}

/* Returns number of file entries seen. Sets ggcc_init_blob if "init" found. */
int ggcc_cpio_scan_init(const char *buf, unsigned long len)
{
	unsigned long off = 0;
	int files = 0;

	ggcc_init_blob = 0;
	ggcc_init_blob_len = 0;
	ggcc_busybox_blob = 0;
	ggcc_busybox_blob_len = 0;
	if (!buf || len < 110)
		return 0;
	while (off + 110 <= len) {
		const char *h = buf + off;
		unsigned long namesize, filesize, name_off, data_off, next;
		const char *name;

		if (h[0] != '0' || h[1] != '7' || h[2] != '0' || h[3] != '7' ||
		    h[4] != '0' || h[5] != '1')
			break;
		namesize = ggcc_hex8(h + 94);
		filesize = ggcc_hex8(h + 54);
		name_off = off + 110;
		if (name_off + namesize > len)
			break;
		name = buf + name_off;
		data_off = (name_off + namesize + 3) & ~3UL;
		next = (data_off + filesize + 3) & ~3UL;
		if (next > len)
			break;
		if (namesize >= 11 && name[0] == 'T' && name[1] == 'R' && name[2] == 'A')
			break; /* TRAILER!!! */
		files++;
		if (ggcc_str_eq(name, "init") || ggcc_str_eq(name, "/init")) {
			ggcc_init_blob = (unsigned long)(buf + data_off);
			ggcc_init_blob_len = filesize;
			_printk("ggcc_cpio: found /init\n");
		} else if (ggcc_str_eq(name, "bin/busybox") ||
			   ggcc_str_eq(name, "/bin/busybox")) {
			ggcc_busybox_blob = (unsigned long)(buf + data_off);
			ggcc_busybox_blob_len = filesize;
			_printk("ggcc_cpio: found bin/busybox\n");
		}
		off = next;
	}
	return files;
}

/*
 * Global populate_rootfs for rest_init (real one is static rootfs_initcall and
 * ggcc drops it as unreachable). Scans initrd cpio without VFS.
 * Runs after map_mem — use linear map for FDT + initrd.
 */
char *unpack_to_rootfs(char *buf, unsigned long len)
{
	const unsigned char *b;

	_printk("Unpacking initramfs (freestanding scan, no VFS)\n");
	if (!buf || !len)
		return 0;
	b = (const unsigned char *)buf;
	if (b[0] == 0x1f && b[1] == 0x8b) {
		_printk("unpack: gzip initrd — need decompress before cpio (blocked)\n");
		return 0;
	}
	ggcc_cpio_scan_init(buf, len);
	_printk("unpack_to_rootfs: freestanding scan done\n");
	return 0;
}

/*
 * A08 x86_64: freestanding ELF load of cpio busybox → ring3 + SYSCALL stubs.
 * PAGE_OFFSET_L4 = 0xffff888000000000 (tinyconfig / non-randomized).
 */
extern void *memcpy(void *dst, const void *src, unsigned long n);
extern void *memset(void *dst, int c, unsigned long n);
extern void ggcc_el0_enter(unsigned long entry, unsigned long sp_user,
			   unsigned long cr3_phys);
extern void ggcc_uart_nwrite(const char *buf, unsigned long n);
extern void ggcc_cache_flush_range(unsigned long start, unsigned long size);
extern void ggcc_set_tpidr_el0(unsigned long v);
extern unsigned long ggcc_read_cr3(void);

#define GGCC_PAGE_OFFSET	0xffff888000000000ULL
#define GGCC_LIN(phys)		((unsigned long)(GGCC_PAGE_OFFSET + (unsigned long)(phys)))

#define GGCC_USER_PHYS	0x10000000UL
#define GGCC_PT_PHYS	0x0f000000UL
#define GGCC_STACK_PHYS	0x11000000UL
#define GGCC_STACK_VA	0x01000000UL
#define GGCC_STACK_SZ	0x10000UL
#define GGCC_ELF_BASE	0x00400000UL

#define GGCC_USER_LIN	GGCC_LIN(GGCC_USER_PHYS)
#define GGCC_PT_LIN	GGCC_LIN(GGCC_PT_PHYS)
#define GGCC_STACK_LIN	GGCC_LIN(GGCC_STACK_PHYS)

/* PTE flags: present|rw|user|accessed|dirty ; PS for 2MB */
#define GGCC_PTE_USER	0x067UL
#define GGCC_PDE_PS	0x080UL

static unsigned long ggcc_brk_cur;
static unsigned long ggcc_brk_base;
static char ggcc_wrbuf[256];
static char ggcc_rnd[16];

extern unsigned char boot_params[];

int populate_rootfs(void)
{
	unsigned long start;
	unsigned long end;
	unsigned int rd_img = 0, rd_sz = 0;
	const unsigned char *bp;

	_printk("populate_rootfs: freestanding x86_64 (unpack_to_rootfs)\n");
	start = initrd_start;
	end = initrd_end;
	if (!start || end <= start) {
		/* Zero-page: ramdisk_image @0x218, ramdisk_size @0x21c */
		bp = (const unsigned char *)boot_params;
		rd_img = (unsigned int)bp[0x218] | ((unsigned int)bp[0x219] << 8) |
			 ((unsigned int)bp[0x21a] << 16) | ((unsigned int)bp[0x21b] << 24);
		rd_sz = (unsigned int)bp[0x21c] | ((unsigned int)bp[0x21d] << 8) |
			((unsigned int)bp[0x21e] << 16) | ((unsigned int)bp[0x21f] << 24);
		if (rd_img && rd_sz) {
			phys_initrd_start = rd_img;
			phys_initrd_size = rd_sz;
			start = GGCC_LIN(rd_img);
			end = start + rd_sz;
			initrd_start = start;
			initrd_end = end;
			_printk("populate_rootfs: initrd from boot_params\n");
		}
	}
	if (!start || end <= start) {
		_printk("populate_rootfs: no initrd (initrd_start=0)\n");
		return 0;
	}
	unpack_to_rootfs((char *)start, end - start);
	return 0;
}

static unsigned long *ggcc_pt_page(unsigned long page_idx)
{
	return (unsigned long *)(GGCC_PT_LIN + (page_idx << 12));
}

static void ggcc_zero_page(unsigned long *p)
{
	unsigned long i;
	for (i = 0; i < 512; i++)
		p[i] = 0;
}

/* Build user CR3: copy kernel PML4[256..511], add 2MB user maps. */
static unsigned long ggcc_build_user_cr3(void)
{
	unsigned long *pml4 = ggcc_pt_page(0);
	unsigned long *pdpt = ggcc_pt_page(1);
	unsigned long *pd = ggcc_pt_page(2);
	unsigned long *pd_stack = ggcc_pt_page(3);
	unsigned long *cur;
	unsigned long cr3, i;
	unsigned long pdpt_phys = GGCC_PT_PHYS + 0x1000UL;
	unsigned long pd_phys = GGCC_PT_PHYS + 0x2000UL;
	unsigned long pd_stack_phys = GGCC_PT_PHYS + 0x3000UL;

	ggcc_zero_page(pml4);
	ggcc_zero_page(pdpt);
	ggcc_zero_page(pd);
	ggcc_zero_page(pd_stack);

	cr3 = ggcc_read_cr3() & ~0xfffUL;
	cur = (unsigned long *)GGCC_LIN(cr3);
	for (i = 256; i < 512; i++)
		pml4[i] = cur[i];

	pml4[0] = pdpt_phys | 0x007UL; /* present|rw|user */
	pdpt[0] = pd_phys | 0x007UL;
	for (i = 0; i < 512; i++)
		pd[i] = (i << 21) | GGCC_PTE_USER | GGCC_PDE_PS;
	/* VA 0x400000..0x9fffff → USER_PHYS (3×2MB) */
	for (i = 0; i < 3; i++) {
		unsigned long va_idx = 2UL + i;
		unsigned long phys = GGCC_USER_PHYS + (i << 21);
		pd[va_idx] = (phys & ~0x1fffffUL) | GGCC_PTE_USER | GGCC_PDE_PS;
	}
	/* Heap 0xa00000..0xffffff */
	for (i = 0; i < 3; i++) {
		unsigned long va_idx = 5UL + i;
		unsigned long phys = GGCC_USER_PHYS + ((3UL + i) << 21);
		pd[va_idx] = (phys & ~0x1fffffUL) | GGCC_PTE_USER | GGCC_PDE_PS;
	}
	/* Low VA 0..2MB for TLS slot @0x740 */
	pd[0] = ((GGCC_STACK_PHYS + 0x200000UL) & ~0x1fffffUL) | GGCC_PTE_USER | GGCC_PDE_PS;
	/* Stack VA 0x1000000 — needs PDPT/PD for VA>>30 */
	/* 0x1000000 >> 21 = 8 — same PD if <1GB */
	pd[GGCC_STACK_VA >> 21] = (GGCC_STACK_PHYS & ~0x1fffffUL) | GGCC_PTE_USER | GGCC_PDE_PS;
	(void)pd_stack;
	(void)pd_stack_phys;

	return GGCC_PT_PHYS;
}

static int ggcc_load_busybox_elf(unsigned long blob, unsigned long blob_len,
				 unsigned long *entry_out)
{
	const unsigned char *e;
	unsigned long phoff, phentsize, phnum, entry;
	unsigned long i;

	if (!blob || blob_len < 64)
		return -1;
	e = (const unsigned char *)blob;
	if (e[0] != 0x7f || e[1] != 'E' || e[2] != 'L' || e[3] != 'F')
		return -1;
	entry = (unsigned long)e[24] | ((unsigned long)e[25] << 8) |
		((unsigned long)e[26] << 16) | ((unsigned long)e[27] << 24) |
		((unsigned long)e[28] << 32) | ((unsigned long)e[29] << 40) |
		((unsigned long)e[30] << 48) | ((unsigned long)e[31] << 56);
	phoff = (unsigned long)e[32] | ((unsigned long)e[33] << 8) |
		((unsigned long)e[34] << 16) | ((unsigned long)e[35] << 24) |
		((unsigned long)e[36] << 32) | ((unsigned long)e[37] << 40) |
		((unsigned long)e[38] << 48) | ((unsigned long)e[39] << 56);
	phentsize = (unsigned long)e[54] | ((unsigned long)e[55] << 8);
	phnum = (unsigned long)e[56] | ((unsigned long)e[57] << 8);
	if (phentsize < 56 || phnum == 0 || phnum > 64)
		return -1;

	for (i = 0; i < phnum; i++) {
		const unsigned char *ph = e + phoff + i * phentsize;
		unsigned int p_type;
		unsigned long p_offset, p_vaddr, p_filesz, p_memsz;
		unsigned long dest;

		p_type = (unsigned int)ph[0] | ((unsigned int)ph[1] << 8) |
			 ((unsigned int)ph[2] << 16) | ((unsigned int)ph[3] << 24);
		if (p_type != 1)
			continue;
		p_offset = (unsigned long)ph[8] | ((unsigned long)ph[9] << 8) |
			   ((unsigned long)ph[10] << 16) | ((unsigned long)ph[11] << 24) |
			   ((unsigned long)ph[12] << 32) | ((unsigned long)ph[13] << 40) |
			   ((unsigned long)ph[14] << 48) | ((unsigned long)ph[15] << 56);
		p_vaddr = (unsigned long)ph[16] | ((unsigned long)ph[17] << 8) |
			  ((unsigned long)ph[18] << 16) | ((unsigned long)ph[19] << 24) |
			  ((unsigned long)ph[20] << 32) | ((unsigned long)ph[21] << 40) |
			  ((unsigned long)ph[22] << 48) | ((unsigned long)ph[23] << 56);
		p_filesz = (unsigned long)ph[32] | ((unsigned long)ph[33] << 8) |
			   ((unsigned long)ph[34] << 16) | ((unsigned long)ph[35] << 24) |
			   ((unsigned long)ph[36] << 32) | ((unsigned long)ph[37] << 40) |
			   ((unsigned long)ph[38] << 48) | ((unsigned long)ph[39] << 56);
		p_memsz = (unsigned long)ph[40] | ((unsigned long)ph[41] << 8) |
			  ((unsigned long)ph[42] << 16) | ((unsigned long)ph[43] << 24) |
			  ((unsigned long)ph[44] << 32) | ((unsigned long)ph[45] << 40) |
			  ((unsigned long)ph[46] << 48) | ((unsigned long)ph[47] << 56);
		if (p_vaddr < GGCC_ELF_BASE)
			return -1;
		if (p_offset + p_filesz > blob_len)
			return -1;
		dest = GGCC_USER_LIN + (p_vaddr - GGCC_ELF_BASE);
		if (p_filesz)
			memcpy((void *)dest, (const void *)(blob + p_offset), p_filesz);
		if (p_memsz > p_filesz)
			memset((void *)(dest + p_filesz), 0, p_memsz - p_filesz);
		if (p_vaddr + p_memsz > ggcc_brk_base)
			ggcc_brk_base = p_vaddr + p_memsz;
	}
	ggcc_brk_cur = (ggcc_brk_base + 0xfff) & ~0xfffUL;
	*entry_out = entry;
	return 0;
}

static unsigned long ggcc_setup_user_stack(unsigned long entry)
{
	unsigned long *sp;
	char *str;
	unsigned long str_va;
	unsigned long i;
	unsigned long sp_va;

	memset((void *)GGCC_STACK_LIN, 0, GGCC_STACK_SZ);
	for (i = 0; i < 16; i++)
		ggcc_rnd[i] = (char)(0xa5 ^ (int)i);

	str = (char *)(GGCC_STACK_LIN + GGCC_STACK_SZ - 64);
	str[0] = 'b'; str[1] = 'u'; str[2] = 's'; str[3] = 'y';
	str[4] = 'b'; str[5] = 'o'; str[6] = 'x'; str[7] = 0;
	memcpy(str + 16, ggcc_rnd, 16);
	str_va = GGCC_STACK_VA + GGCC_STACK_SZ - 64;

	sp = (unsigned long *)(GGCC_STACK_LIN + GGCC_STACK_SZ - 512);
	sp_va = GGCC_STACK_VA + GGCC_STACK_SZ - 512;
	sp[0] = 1;
	sp[1] = str_va;
	sp[2] = 0;
	sp[3] = 0;
	sp[4] = 3;			/* AT_PHDR */
	sp[5] = GGCC_ELF_BASE + 64;
	sp[6] = 4;			/* AT_PHENT */
	sp[7] = 56;
	sp[8] = 5;			/* AT_PHNUM */
	sp[9] = 10;
	sp[10] = 6;			/* AT_PAGESZ */
	sp[11] = 4096;
	sp[12] = 9;			/* AT_ENTRY */
	sp[13] = entry;
	sp[14] = 11;
	sp[15] = 0;
	sp[16] = 12;
	sp[17] = 0;
	sp[18] = 13;
	sp[19] = 0;
	sp[20] = 14;
	sp[21] = 0;
	sp[22] = 17;
	sp[23] = 100;
	sp[24] = 23;
	sp[25] = 0;
	sp[26] = 25;
	sp[27] = str_va + 16;
	sp[28] = 31;
	sp[29] = str_va;
	sp[30] = 0;
	sp[31] = 0;
	return sp_va;
}

static unsigned long ggcc_u2k(unsigned long uva)
{
	if (uva >= GGCC_ELF_BASE && uva < GGCC_ELF_BASE + 0x600000UL)
		return GGCC_USER_LIN + (uva - GGCC_ELF_BASE);
	if (uva >= GGCC_STACK_VA && uva < GGCC_STACK_VA + GGCC_STACK_SZ)
		return GGCC_STACK_LIN + (uva - GGCC_STACK_VA);
	if (uva < 0x200000UL) /* TLS low page */
		return GGCC_LIN(GGCC_STACK_PHYS + 0x200000UL) + uva;
	return 0;
}

long ggcc_el0_svc_c(unsigned long a0, unsigned long a1, unsigned long a2,
		    unsigned long a3, unsigned long a4, unsigned long a5,
		    unsigned long sysno)
{
	(void)a3;
	(void)a4;
	(void)a5;
	/* x86_64 Linux syscall numbers */
	if (sysno == 1) { /* write */
		unsigned long ubuf = a1, count = a2;
		unsigned long done = 0;
		unsigned long kbuf = ggcc_u2k(ubuf);
		if (!kbuf)
			return -14;
		while (done < count) {
			unsigned long n = count - done;
			unsigned long i;
			if (n > 255)
				n = 255;
			for (i = 0; i < n; i++)
				ggcc_wrbuf[i] = *(char *)(kbuf + done + i);
			ggcc_uart_nwrite(ggcc_wrbuf, n);
			done += n;
		}
		return (long)count;
	}
	if (sysno == 12) { /* brk */
		if (a0 == 0)
			return (long)ggcc_brk_cur;
		if (a0 >= ggcc_brk_base && a0 < GGCC_STACK_VA)
			ggcc_brk_cur = a0;
		return (long)ggcc_brk_cur;
	}
	if (sysno == 60 || sysno == 231) { /* exit / exit_group */
		_printk("ggcc_el0: busybox exit\n");
		for (;;)
			;
	}
	if (sysno == 16) /* ioctl */
		return -25;
	if (sysno == 102 || sysno == 104 || sysno == 107 || sysno == 108)
		return 0; /* getuid/getgid/geteuid/getegid */
	if (sysno == 39 || sysno == 186) /* getpid / gettid */
		return 1;
	if (sysno == 218) /* set_tid_address */
		return 1;
	if (sysno == 273) /* set_robust_list */
		return 0;
	if (sysno == 302) /* prlimit64 */
		return 0;
	if (sysno == 10) /* mprotect */
		return 0;
	if (sysno == 9) { /* mmap */
		static unsigned long mmap_bump;
		unsigned long len = a1;
		unsigned long va;
		if (!mmap_bump)
			mmap_bump = 0xa00000UL;
		if (len == 0)
			len = 0x1000;
		len = (len + 0xfff) & ~0xfffUL;
		va = mmap_bump;
		mmap_bump += len;
		if (mmap_bump > 0x1000000UL)
			return -12;
		return (long)va;
	}
	if (sysno == 11) /* munmap */
		return 0;
	if (sysno == 318) { /* getrandom */
		unsigned long i;
		unsigned long kdst = ggcc_u2k(a0);
		char *dst;
		if (!kdst)
			return -14;
		dst = (char *)kdst;
		for (i = 0; i < a1 && i < 256; i++)
			dst[i] = ggcc_rnd[i & 15];
		return (long)((a1 < 256) ? a1 : 256);
	}
	if (sysno == 334) /* rseq */
		return 0;
	if (sysno == 292) /* dup3 */
		return (long)a1;
	if (sysno == 32) /* dup */
		return (long)(a0 + 10);
	if (sysno == 72) /* fcntl */
		return 0;
	if (sysno == 257) /* openat */
		return 3;
	if (sysno == 3) /* close */
		return 0;
	if (sysno == 0) /* read EOF */
		return 0;
	if (sysno == 5 || sysno == 262) /* fstat / newfstatat */
		return -2;
	if (sysno == 63) { /* uname */
		unsigned long kdst = ggcc_u2k(a0);
		char *u;
		if (!kdst)
			return -14;
		u = (char *)kdst;
		memset(u, 0, 390);
		u[0] = 'L'; u[1] = 'i'; u[2] = 'n'; u[3] = 'u'; u[4] = 'x';
		return 0;
	}
	if (sysno == 13 || sysno == 14 || sysno == 15) /* rt_sig* */
		return 0;
	if (sysno == 28) /* madvise */
		return 0;
	if (sysno == 158) /* arch_prctl — ignore */
		return 0;
	{
		char b[24];
		const char *hex = "0123456789abcdef";
		unsigned long v = sysno;
		int i;
		b[0] = 'S'; b[1] = 'Y'; b[2] = 'S'; b[3] = '=';
		for (i = 0; i < 4; i++)
			b[4 + i] = hex[(v >> (12 - 4 * i)) & 0xf];
		b[8] = '\n';
		ggcc_uart_nwrite(b, 9);
	}
	return -38;
}

void ggcc_el0_fault_c(unsigned long esr, unsigned long elr)
{
	(void)esr;
	(void)elr;
	_printk("ggcc_el0: FAULT\n");
}

int ggcc_el0_run_busybox(void)
{
	unsigned long entry = 0;
	unsigned long cr3;
	unsigned long sp;
	unsigned long blob, blen;

	_printk("ggcc_el0: load busybox ELF -> EL0\n");
	blob = ggcc_busybox_blob;
	blen = ggcc_busybox_blob_len;
	if (!blob || !blen) {
		_printk("ggcc_el0: no busybox blob\n");
		return -1;
	}
	_printk("ggcc_el0: blob ok, clearing user RAM\n");
	ggcc_brk_base = GGCC_ELF_BASE;
	ggcc_brk_cur = GGCC_ELF_BASE;
	{
		volatile unsigned char *p = (volatile unsigned char *)GGCC_USER_LIN;
		unsigned long i;
		_printk("ggcc_el0: probe user RAM store\n");
		p[0] = 0x5a;
		if (p[0] != 0x5a) {
			_printk("ggcc_el0: user RAM probe FAIL\n");
			return -1;
		}
		_printk("ggcc_el0: probe ok, memset 3MB\n");
		for (i = 0; i < 0x300000UL; i++)
			p[i] = 0;
	}
	_printk("ggcc_el0: calling ELF loader\n");
	if (ggcc_load_busybox_elf(blob, blen, &entry)) {
		_printk("ggcc_el0: ELF load failed\n");
		return -1;
	}
	_printk("ggcc_el0: cache flush\n");
	ggcc_cache_flush_range(GGCC_USER_LIN, 0x300000UL);
	_printk("ggcc_el0: building TTBR0\n");
	cr3 = ggcc_build_user_cr3();
	_printk("ggcc_el0: setup stack\n");
	sp = ggcc_setup_user_stack(entry);
	ggcc_set_tpidr_el0(0x740UL);
	_printk("ggcc_el0: enter EL0\n");
	ggcc_el0_enter(entry, sp, cr3);
	return -1;
}
